#include <cstddef>
#include <stdexcept>
#include <string>

std::string CompressEventRuns(const std::string& events) {
    const std::size_t kMaxInputBytes = 200000;
    if (events.size() > kMaxInputBytes) {
        throw std::invalid_argument("input is too long");
    }
    for (unsigned char byte : events) {
        if (byte < 'A' || byte > 'Z') {
            throw std::invalid_argument("input must contain ASCII A-Z only");
        }
    }

    std::size_t encodedLength = 0;
    for (std::size_t i = 0; i < events.size();) {
        std::size_t j = i + 1;
        while (j < events.size() && events[j] == events[i]) ++j;
        const std::size_t run = j - i;
        std::size_t digits = 1;
        for (std::size_t value = run; value >= 10; value /= 10) ++digits;
        encodedLength += 1 + digits;
        i = j;
    }
    if (encodedLength >= events.size()) return events;

    std::string encoded;
    encoded.reserve(encodedLength);
    for (std::size_t i = 0; i < events.size();) {
        std::size_t j = i + 1;
        while (j < events.size() && events[j] == events[i]) ++j;
        encoded.push_back(events[i]);
        encoded += std::to_string(j - i);
        i = j;
    }
    return encoded;
}
